def rebuild_line(pairs):
    near = {}
    for x, y in pairs:
        near.setdefault(x, []).append(y)
        near.setdefault(y, []).append(x)
    start = min(s for s, ns in near.items() if len(ns) == 1)
    line = [start]
    prev, cur = None, start
    while True:
        ahead = [s for s in near[cur] if s != prev]
        if not ahead:
            return line
        prev, cur = cur, ahead[0]
        line.append(cur)

